def _usage(node) -> str | None:
    p = getattr(node, "_parent", None)
    if isinstance(p, ast.Call):
        if node is p.func:
            return None
        name = _call_name(p)
220→        if name == "startswith":
            return "prefix"
        if name == "endswith":
