            .unwrap_or_else(|| project_key.trim_start_matches("unknown:").to_string());
        by_project
            .entry(project_key.clone())
590→            .or_insert_with(|| UsageBucket::new(project_key, project_label))
            .add(event);
    }

    let mut by_source: Vec<_> = by_source.into_values().collect();
    by_source.sort_by(|a, b| {
        b.total_tokens
            .cmp(&a.total_tokens)
            .then(a.label.cmp(&b.label))
    });
600→    let mut by_project: Vec<_> = by_project.into_values().collect();
    by_project.sort_by(|a, b| {
        b.total_tokens
            .cmp(&a.total_tokens)
            .then(a.label.cmp(&b.label))
    });

    UsageReport {
        day,
        total,
610→        by_source,
        by_project,
    }
}

