fn cmd_doctor(ctx: &AdapterContext, json_output: bool) -> ExitCode {
    let report = doctor::run(ctx);
    if json_output {
        println!(
            "{}",
            serde_json::to_string_pretty(&report).expect("doctor report JSON is serializable")
        );
    } else {
        print_doctor_report(&report);
    }
    if report.ok {
        ExitCode::SUCCESS
    } else {
        ExitCode::FAILURE
    }
}

fn print_doctor_report(report: &DoctorReport) {
    println!("doctor {}", if report.ok { "ok" } else { "failed" });
    for check in &report.checks {
        let label = match check.status {
            DoctorStatus::Ok => "ok",
            DoctorStatus::Warn => "warn",
            DoctorStatus::Error => "error",
        };
        println!("  [{:<5}] {:<14} {}", label, check.id, check.message);
        if let Some(detail) = check.detail.as_deref() {
            println!("         {}", detail);
        }
    }
}

fn cmd_usage(
    ctx: &AdapterContext,
    sources_filter: Option<&[String]>,
    date: &str,
    json_output: bool,
    from_cache: Option<PathBuf>,
) -> ExitCode {
    let day = match parse_usage_day(date) {
        Ok(day) => day,
        Err(message) => {
            eprintln!("{message}");
            return ExitCode::from(2);
        }
    };
    let events = match build_events(ctx, sources_filter, from_cache.as_deref()) {
        Ok(events) => events,
        Err(code) => return code,
    };
    let report = summarize_usage(&events, day);
    if json_output {
        println!("{}", usage_report_json(&report));
    } else {
        print_usage_report(&report);
    }
    ExitCode::SUCCESS
}

