// ---- shared plumbing ------------------------------------------------------

/// Build a `GardenSummary` from either a cached events.json or a live scan.
/// Returns ExitCode::from(N) on failure so the caller can propagate.
fn build_summary(
    ctx: &AdapterContext,
    sources_filter: Option<&[String]>,
    from_cache: Option<&std::path::Path>,
) -> Result<GardenSummary, ExitCode> {
    let events = build_events(ctx, sources_filter, from_cache)?;
    let summary = aggregate::summarize(&events);
    let rings_path = from_cache
        .map(rings::path_for_events_cache)
        .unwrap_or_else(rings::default_rings_path);
    Ok(rings::record_summary_best_effort(
        summary,
        &rings_path,
        chrono::Utc::now(),
    ))
}

fn build_events(
    ctx: &AdapterContext,
    sources_filter: Option<&[String]>,
    from_cache: Option<&std::path::Path>,
) -> Result<Vec<AgentEvent>, ExitCode> {
    let events = if let Some(cache) = from_cache {
        match storage::load_events(cache) {
            Ok(events) => events,
            Err(err) => {
                eprintln!("read cache {} failed: {}", cache.display(), err);
                return Err(ExitCode::FAILURE);
            }
        }
    } else {
        match scan::collect_events(ctx, sources_filter) {
            Ok(result) => {
                print_scan_failures(&result.failures);
                result.events
            }
            Err(err) => {
                eprintln!("scan failed: {}", err);
                return Err(ExitCode::FAILURE);
            }
        }
    };
    Ok(events)
}

fn print_scan_failures(failures: &[scan::AdapterFailure]) {
    for failure in failures {
        eprintln!(
            "warning: adapter {} failed: {}",
            failure.adapter, failure.message
        );
    }
}

#[derive(Default)]
struct UsageBucket {
    key: String,
    label: String,
    total_tokens: u64,
    input_tokens: u64,
    output_tokens: u64,
    cache_read_tokens: u64,
    cache_write_tokens: u64,
    event_count: u64,
    sessions: BTreeSet<String>,
    sources: BTreeMap<String, u64>,
}

impl UsageBucket {
    fn new(key: impl Into<String>, label: impl Into<String>) -> Self {
        Self {
            key: key.into(),
            label: label.into(),
            ..Default::default()
        }
    }

    fn add(&mut self, event: &AgentEvent) {
        self.total_tokens += event.usage.total_tokens;
        self.input_tokens += event.usage.input_tokens;
        self.output_tokens += event.usage.output_tokens;
        self.cache_read_tokens += event.usage.cache_read_tokens;
        self.cache_write_tokens += event.usage.cache_write_tokens;
        self.event_count += 1;
        *self.sources.entry(event.source.clone()).or_insert(0) += 1;
        if let Some(session_id) = event.session_id.as_ref() {
            self.sessions.insert(session_id.clone());
        }
    }
}

struct UsageReport {
    day: NaiveDate,
    total: UsageBucket,
    by_source: Vec<UsageBucket>,
    by_project: Vec<UsageBucket>,
}

fn summarize_usage(events: &[AgentEvent], day: NaiveDate) -> UsageReport {
    let mut total = UsageBucket::new("all", "all agents");
    let mut by_source: BTreeMap<String, UsageBucket> = BTreeMap::new();
    let mut by_project: BTreeMap<String, UsageBucket> = BTreeMap::new();

    for event in events {
        if event.timestamp.with_timezone(&Local).date_naive() != day {
            continue;
        }
        total.add(event);

        by_source
            .entry(event.source.clone())
            .or_insert_with(|| UsageBucket::new(&event.source, &event.source))
            .add(event);

        let project_key = event.project_key();
        let project_label = event
            .project_path
            .as_deref()
            .map(display_name_from_path)
            .unwrap_or_else(|| project_key.trim_start_matches("unknown:").to_string());
        by_project
            .entry(project_key.clone())
            .or_insert_with(|| UsageBucket::new(project_key, project_label))
            .add(event);
    }

    let mut by_source: Vec<_> = by_source.into_values().collect();
    by_source.sort_by(|a, b| {
        b.total_tokens
            .cmp(&a.total_tokens)
            .then(a.label.cmp(&b.label))
    });
    let mut by_project: Vec<_> = by_project.into_values().collect();
    by_project.sort_by(|a, b| {
        b.total_tokens
            .cmp(&a.total_tokens)
            .then(a.label.cmp(&b.label))
    });

    UsageReport {
        day,
        total,
        by_source,
        by_project,
    }
}

fn parse_usage_day(value: &str) -> Result<NaiveDate, String> {
    let today = Local::now().date_naive();
    match value {
        "" | "today" => Ok(today),
        "yesterday" => Ok(today.pred_opt().unwrap_or(today)),
        other => NaiveDate::parse_from_str(other, "%Y-%m-%d")
            .map_err(|_| format!("invalid --date {other:?}; use today, yesterday, or YYYY-MM-DD")),
    }
}

fn print_usage_report(report: &UsageReport) {
    println!("usage for {}", report.day.format("%Y-%m-%d"));
    println!();
    println!("total");
    print_bucket("all agents", &report.total);

    println!();
    println!("by source");
    if report.by_source.is_empty() {
        println!("  -");
    } else {
        for bucket in &report.by_source {
            print_bucket(&bucket.label, bucket);
        }
    }

    println!();
    println!("by project");
    if report.by_project.is_empty() {
        println!("  -");
    } else {
        for bucket in report.by_project.iter().take(20) {
            print_bucket(&bucket.label, bucket);
        }
        if report.by_project.len() > 20 {
            println!("  ... {} more", report.by_project.len() - 20);
        }
    }
}

fn print_bucket(label: &str, bucket: &UsageBucket) {
    println!(
        "  {:<28} tokens={:<10} input={:<10} output={:<10} cache={:<10} events={:<5} sessions={}",
        truncate(label, 28),
        bucket.total_tokens,
        bucket.input_tokens,
        bucket.output_tokens,
        bucket.cache_read_tokens + bucket.cache_write_tokens,
        bucket.event_count,
        bucket.sessions.len(),
    );
}

fn usage_report_json(report: &UsageReport) -> String {
    let value = json!({
        "date": aggregate::day_key(report.day),
        "total": bucket_json(&report.total),
        "by_source": report.by_source.iter().map(bucket_json).collect::<Vec<_>>(),
        "by_project": report.by_project.iter().map(bucket_json).collect::<Vec<_>>(),
    });
    serde_json::to_string_pretty(&value).expect("usage report JSON is serializable")
}

fn bucket_json(bucket: &UsageBucket) -> serde_json::Value {
    json!({
        "key": bucket.key,
        "label": bucket.label,
        "total_tokens": bucket.total_tokens,
        "input_tokens": bucket.input_tokens,
        "output_tokens": bucket.output_tokens,
        "cache_read_tokens": bucket.cache_read_tokens,
        "cache_write_tokens": bucket.cache_write_tokens,
        "event_count": bucket.event_count,
        "sessions": bucket.sessions.len(),
        "sources": bucket.sources,
    })
}

fn display_name_from_path(path: &str) -> String {
    PathBuf::from(path)
        .file_name()
        .and_then(|s| s.to_str())
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| path.to_string())
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        let mut out: String = s.chars().take(max - 1).collect();
        out.push('…');
        out
    }
}

fn bail<E: std::fmt::Display>(prefix: &str, err: E) -> ExitCode {
    eprintln!("{}: {}", prefix, err);
    ExitCode::FAILURE
}

#[derive(Debug, PartialEq, Eq)]
struct AdapterReport {
    name: String,
    discovered: bool,
    status: &'static str,
    watch_paths: Vec<String>,
}

fn adapter_reports(
    ctx: &AdapterContext,
    sources_filter: Option<&[String]>,
    include_watch_paths: bool,
) -> Vec<AdapterReport> {
    registry::default_adapters()
        .into_iter()
        .filter(|adapter| source_allowed(adapter.name(), sources_filter))
        .map(|adapter| {
            let discovered = adapter.discover(ctx);
            let watch_paths = if include_watch_paths {
                adapter
                    .watch_paths(ctx)
                    .into_iter()
                    .map(|path| path.display().to_string())
                    .collect()
            } else {
                Vec::new()
            };
            AdapterReport {
                name: adapter.name().to_string(),
                discovered,
                status: if discovered { "active" } else { "available" },
                watch_paths,
            }
        })
        .collect()
}

fn source_allowed(name: &str, sources_filter: Option<&[String]>) -> bool {
    sources_filter
        .map(|sources| sources.iter().any(|source| source == name))
        .unwrap_or(true)
}

fn adapter_reports_json(reports: &[AdapterReport]) -> Value {
    json!({
        "adapters": reports.iter().map(|report| {
            json!({
                "name": report.name,
                "discovered": report.discovered,
                "status": report.status,
                "watch_paths": report.watch_paths,
            })
        }).collect::<Vec<_>>(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn adapter_reports_filter_without_scanning() {
        let ctx = AdapterContext::with_home(std::env::temp_dir());
        let filter = vec!["manual-jsonl".to_string()];

        let reports = adapter_reports(&ctx, Some(&filter), false);

        assert_eq!(reports.len(), 1);
        assert_eq!(reports[0].name, "manual-jsonl");
        assert!(!reports[0].discovered);
        assert_eq!(reports[0].status, "available");
        assert!(reports[0].watch_paths.is_empty());
    }

    #[test]
    fn adapter_reports_can_include_watch_paths() {
        let manual = PathBuf::from("agent-events.jsonl");
        let ctx = AdapterContext::with_home(std::env::temp_dir()).with_manual_jsonl([manual]);
        let filter = vec!["manual-jsonl".to_string()];

        let reports = adapter_reports(&ctx, Some(&filter), true);

        assert_eq!(reports.len(), 1);
        assert_eq!(reports[0].status, "active");
        assert_eq!(reports[0].watch_paths, vec!["agent-events.jsonl"]);
    }

    #[test]
    fn adapter_report_json_has_stable_shape() {
        let reports = vec![AdapterReport {
            name: "manual-jsonl".to_string(),
            discovered: true,
            status: "active",
            watch_paths: vec!["events.jsonl".to_string()],
        }];

        assert_eq!(
            adapter_reports_json(&reports),
            json!({
                "adapters": [{
                    "name": "manual-jsonl",
                    "discovered": true,
                    "status": "active",
                    "watch_paths": ["events.jsonl"],
                }]
            })
        );
    }
}
